-- 0052_food_recettes_import_lot3.sql
-- STATUT: PROPOSITION
-- Auteur : Claude Code · Date de rédaction : 2026-10-29
-- Objet : import des fiches recettes transmises par Renée-Lise —
--   lot 3/7 (10 fiches sur 68 au total).
--   Fractionné en petits lots collables depuis le téléphone (comme
--   l'import Concorde Pro). Toutes les fiches restent en statut
--   brouillon, aucune publication. Réutilise food_recettes sans
--   modification de schéma (migration 0049).
--
--   Fiches de ce lot : Jus de canne fraîche, Boisson artisanale à la mangue, Boisson à la pomme rosa, Boisson à la cerise pays, Boisson fraîche à la pastèque, Eau de coco naturelle, Boisson à la goyave, Boisson au corossol, Boisson au cupuaçu, Boisson à la prune de cythère
--
-- Déduplication : chaque fiche reçoit source = 'bf_import:<id_import>' ;
--   l'INSERT ignore toute ligne dont ce "source" existe déjà — rejouer
--   ce lot ne duplique jamais rien.
-- Impact : additif uniquement, idempotent.
-- ═══════════════════════════════════════════════════════════

with donnees as (
  select *
  from jsonb_to_recordset($import$
[{"source":"bf_import:bf_jus_canne","nom":"Jus de canne fraîche","categorie":"jus","sous_cat":"bati_vilo","nb_parts":1,"ingredients":[{"id":"bf_jus_canne_ing1","nom":"Canne à sucre préparée","unite":"g","quantite":2000,"quantite_min":null,"quantite_max":null,"notes":"Masse d’essai, rendement d’extraction réel inconnu","provenance":"formulation_essai_non_validee"}],"etapes":["Presser la canne avec un extracteur propre et adapté.","Filtrer si nécessaire, mesurer le volume réellement obtenu.","Conditionner immédiatement en contenant alimentaire propre et refroidir conformément à la procédure validée."],"allergenes":["selon ingrédients ajoutés et contaminations croisées"],"tags":["bati_vilo","boisson_locale","jus_boisson","saveur_a_etudier"],"notes":"[Origine : formulation_essai_non_validee · Offre : saveur_a_etudier]\n\nPressage sans ajout d’eau garanti seulement si réellement réalisé ; ne pas annoncer « sans conservateur » sans vérification. Les volumes d’essai ne sont pas des rendements garantis. Formule et dénomination commerciale à confirmer.\n\nÀ vérifier avant toute validation : Rendement après extraction/filtration · Volume exact conditionné · Traçabilité et hygiène de préparation · Mode et durée de conservation validés · Étiquette et dénomination légale du produit\n\nRendement de référence (source) : 1 lot cible 1 L (rendement à mesurer) — rendement réel à mesurer"},{"source":"bf_import:bf_boisson_mangue","nom":"Boisson artisanale à la mangue","categorie":"jus","sous_cat":"bati_vilo","nb_parts":1,"ingredients":[{"id":"bf_boisson_mangue_ing1","nom":"Mangue fraîche, pulpe préparée","unite":"g","quantite":600,"quantite_min":null,"quantite_max":null,"notes":"Essai pour un volume final proche de 1 L","provenance":"formulation_essai_non_validee"},{"id":"bf_boisson_mangue_ing2","nom":"Eau potable","unite":"ml","quantite":null,"quantite_min":null,"quantite_max":null,"notes":"Compléter jusqu’au volume après mesure de la pulpe","provenance":"formulation_essai_non_validee